  let atlasIndex=0,atlasZoom=1;
  function renderAtlas(){document.querySelector('#atlas-title').textContent=atlasTitles[atlasIndex];document.querySelector('#atlas-count').textContent=`${atlasIndex+1} / 14 · ${atlasZoom.toFixed(1)}×`;document.querySelector('#atlas-image').src=`./assets/atlas/${String(atlasIndex+1).padStart(2,'0')}.webp`;document.querySelector('#atlas-image').alt=atlasTitles[atlasIndex];document.querySelector('#atlas-image').style.transform=`scale(${atlasZoom})`;document.querySelector('#atlas-caption').textContent=atlasIndex<5?'Дальний вид планеты: живые проводящие магистрали под оболочкой. Увеличьте изображение, чтобы рассмотреть структуру.':atlasIndex<7?'Поверхность: колонии, переходы и следы старых каналов.':atlasIndex<13?'Внутренние биомы: память и проводящие ткани становятся сложнее ближе к сердцевине.':'Общий визуальный поиск грибной морфологии; игровые сцены следуют закреплённому канону.'}
  function openAtlas(index=0){atlasIndex=index;atlasZoom=1;renderAtlas();atlas.classList.add('show');keys.clear();document.querySelector('#atlas-close').focus()}
