  document.querySelector('#atlas-zoom-in').addEventListener('click',()=>{atlasZoom=Math.min(3,+(atlasZoom+.25).toFixed(2));renderAtlas()});document.querySelector('#atlas-zoom-out').addEventListener('click',()=>{atlasZoom=Math.max(1,+(atlasZoom-.25).toFixed(2));renderAtlas()});document.querySelector('#atlas-zoom-reset').addEventListener('click',()=>{atlasZoom=1;renderAtlas()});
  document.querySelector('#atlas-image-wrap').addEventListener('wheel',e=>{e.preventDefault();atlasZoom=Math.max(1,Math.min(3,+(atlasZoom+(e.deltaY<0?.25:-.25)).toFixed(2)));renderAtlas()},{passive:false});
  function stat(key){return character.stats[key]||1}
  function lockBuild(){progress.buildLocked=true}
  function renderHero(){document.querySelector('#hero-cloak').value=character.cloak;document.querySelector('#hero-mark').value=character.mark;const remaining=11-Object.values(character.stats).reduce((a,b)=>a+b,0);document.querySelector('#hero-points').textContent=`Свободные очки: ${remaining} · значения 1–4 · ${progress.buildLocked?'сборка закреплена':'первое особое действие закрепит сборку'}`;const grid=document.querySelector('#hero-stats');grid.replaceChildren();for(const key of statKeys){const card=document.createElement('div'),name=document.createElement('strong'),desc=document.createElement('small'),down=document.createElement('button'),up=document.createElement('button');card.className='hero-stat';name.textContent=`${statNames[key]} · ${stat(key)}`;desc.textContent=statDescriptions[key];down.textContent='−';up.textContent='+';down.type=up.type='button';down.disabled=progress.buildLocked||stat(key)<=1;up.disabled=progress.buildLocked||stat(key)>=4||remaining<=0;down.addEventListener('click',()=>{character.stats[key]--;save();renderHero()});up.addEventListener('click',()=>{character.stats[key]++;save();renderHero()});card.append(name,desc,down,up);grid.append(card)}document.querySelector('#hero-impact').textContent=statKeys.filter(key=>stat(key)>=3).map(key=>({strength:'Сила: удержать сигнальный шлюз.',intellect:'Интеллект: вывести фазу переходника.',endurance:'Выносливость: долгий контакт со спорами.',agility:'Ловкость: настроить движущиеся рецепторы.',sensitivity:'Чуткость: считать ритм без отбора спор.'})[key]).join(' · ')||'Порог 3 открывает особый способ действия у подходящего объекта.'}
  function openHero(){renderHero();heroPanel.classList.add('show');keys.clear();document.querySelector('#hero-close').focus()}
  function closeHero(){heroPanel.classList.remove('show');last=0}
  document.querySelector('#hero-button').addEventListener('click',openHero);document.querySelector('#hero-close').addEventListener('click',closeHero);
  for(const key of ['cloak','mark'])document.querySelector('#hero-'+key).addEventListener('change',e=>{character[key]=e.target.value;save();renderHero()});
  function showMap(){for(const el of document.querySelectorAll('.map-node')){const node=el.dataset.scene;el.classList.toggle('current',node===scene);el.classList.toggle('locked',node==='center'&&!progress.ringAligned||node==='r'&&!(progress.carrierRead&&progress.saltTime&&progress.sporeOrigin)||['b1','c1'].includes(node)&&!progress.carrierRead||node==='b0'&&!progress.saltVisited||node==='c0'&&!progress.choirVisited||node==='carrier'&&!progress.seamCalibrated||node==='memory'&&!progress.relay||node==='seam'&&!progress.ending||node==='atrium'&&scene==='ash'&&!progress.ashCompared&&!progress.ashPassage)}keys.clear();worldMap.classList.add('show');document.querySelector('#map-close').focus({preventScroll:true})}
  function closeMap(){worldMap.classList.remove('show');last=0}
  document.querySelector('#map-button').addEventListener('click',showMap);document.querySelector('#map-close').addEventListener('click',closeMap);
  function message(t,seconds=4){prompt.textContent=t;noticeUntil=elapsed+seconds}
  function inspectionMotion(id){
    const key=id.toLowerCase();
    if(/gate|door|return|back|passage|bridge|iris|surface|^seamto|^saltto|^choirto/.test(key))return 'growth';
    if(/spore|bowl|choirold|choirlate|forestlamella|ashroots/.test(key))return 'spores';
    if(/water|saltcut|deaddetour/.test(key))return 'water';
    if(/recorder|archive|register|chronicle|witness|filter|clock|stamp|hostlog|registry|saltcore/.test(key))return 'scan';
    if(/terminal|console|processor|limiter|contour|ringsalt|ringmemory/.test(key))return 'weave';
    return 'resonance';
  }
