    if(id==='gate'){if(progress.relay){nextScene('memory');return}if(!progress.routePowered){dialog('СИГНАЛЬНЫЙ ШЛЮЗ','Нет питания','Консоль Нулевого узла ещё не направила питание к живым рецепторам шлюза.');return}const options=[{label:'НАСТРОИТЬ РЕЦЕПТОРЫ',action:puzzle}];if(stat('agility')>=3)options.push({label:'ПОЙМАТЬ РИТМ · ЛОВКОСТЬ 3',action:()=>{lockBuild();progress.relay=true;progress.relayMethod='точная настройка';save();goal();dialog('СИГНАЛЬНЫЙ ШЛЮЗ','Ритм пойман','Вы настроили движущиеся ламеллы в момент отклика. Проход остаётся открытым.')}});if(stat('strength')>=3)options.push({label:'УДЕРЖАТЬ МЕМБРАНУ · СИЛА 3',action:()=>{lockBuild();progress.relay=true;progress.relayMethod='ручное удержание';save();goal();dialog('СИГНАЛЬНЫЙ ШЛЮЗ','Ткань удержана','Вы удержали напоённые ламеллы, пока биокерамика закрепила их положение. Проход остаётся открытым.')}});dialog('СИГНАЛЬНЫЙ ШЛЮЗ','Настройка у объекта','Консоль подала питание, но три рецептора шлюза ещё не согласованы. Архив эха хранит порядок импульсов. Выберите способ открыть мембрану.',options)}
