    if(id==='core'){if(!progress.signal){dialog('ПОРТАЛ ПАМЯТИ','Узел спит','Сначала считайте споровый образец и направьте его через пульт.');return}const choose=(ending)=>{progress.ending=ending;save();goal();dialog('ГЛАВА I / ИСХОД',ending==='listen'?'Ответ принят':'Канал изолирован',ending==='listen'?'Вы открыли канал. Новый, незарегистрированный сигнал произносит имя, которого вы не помните. Неясно, принадлежит ли он тому же собеседнику, что говорил через споры.':'Вы закрыли внешний канал. Перед затуханием сигнал оставил координаты неизвестной ветви в памяти узла.',[{label:'ИДТИ К ШВУ РАЗРЫВА',action:()=>{close();nextScene('seam')}}]);};if(progress.ending){dialog('ПОРТАЛ ПАМЯТИ','Путь к Шву',progress.ending==='listen'?'Принятый сигнал указывает на шов в глубине памяти.':'Изолированный сигнал оставил координаты шва в глубине памяти.',[{label:'ИДТИ К ШВУ РАЗРЫВА',action:()=>{close();nextScene('seam')}}])}else if(!progress.node){dialog('ПОРТАЛ ПАМЯТИ','Прямое сопряжение','Гнездо выросло внутри грибного плодового тела. Теперь переходник может удержать связь с живой сетью без спорового облака. Подключиться?', [{label:'ПОДКЛЮЧИТЬ ПЕРЕХОДНИК',action:()=>{progress.node=true;save();goal();dialog('УЗЕЛ 01 ВОССТАНОВЛЕН','Внешний ответ','Контакт с грибницей стал устойчивым; от дальних колоний к центру бегут янтарные импульсы. Следом приходит другой, незарегистрированный ответ. Принять новый сигнал или изолировать его?',[{label:'СЛУШАТЬ ОТВЕТ',action:()=>choose('listen')},{label:'ИЗОЛИРОВАТЬ',action:()=>choose('seal')}]);message('УЗЕЛ 01 ВОССТАНОВЛЕН // ОБНАРУЖЕН ВНЕШНИЙ ОТВЕТ',8)}}])}else dialog('УЗЕЛ 01 ВОССТАНОВЛЕН','Внешний ответ','Связь с грибницей действует. Незарегистрированный ответ ещё ждёт решения.',[{label:'СЛУШАТЬ ОТВЕТ',action:()=>choose('listen')},{label:'ИЗОЛИРОВАТЬ',action:()=>choose('seal')}])}
    if(id==='chronicle')collectTrace('chronicle','ХРОНИКА СОЗДАТЕЛЕЙ','Официальная версия','Лента под треснувшими часами перепечатана. Снимите её оттиск для сравнения с живым следом.',lore.chronicle.text,'СНЯТЬ ОТТИСК');
    if(id==='rift'){if(!progress.echo)collectTrace('echo','ШОВ ПАМЯТИ','Иная последовательность',progress.ending==='listen'?'Принятый сигнал усиливает отпечаток в живой ткани. Прослушайте его отдельно от хроники.':'В спорах остался слабый голос даже после изоляции канала. Прослушайте отпечаток отдельно от хроники.',lore.echo2.text,'ПРОСЛУШАТЬ СЛЕД');else if(progress.seamCalibrated)dialog('ЖИВОЙ ШОВ','След исправления',lore.comparison.text);else if(progress.seamReady)seamPuzzle();else dialog('ЖИВОЙ ШОВ','Два следа ещё не сопоставлены',lore.echo2.text+' Прочтите хронику и разрешите безопасное сравнение на пульте справа.');}
    if(id==='sealedArch'){if(!progress.seamCalibrated){dialog('ЗАПЕЧАТАННАЯ ВЕТВЬ','Нет согласованного следа','Арка не откроется, пока пульт не сопоставит две записи Разрыва.');return}if(progress.archSeen){nextScene('carrier');return}dialog('ЗАПЕЧАТАННАЯ ВЕТВЬ','Арка отвечает','Сопоставленная запись приоткрыла арку. За ней видна отдельная камера с носителем вне реестра PRIMUS.',[{label:'ВОЙТИ К НОСИТЕЛЮ',action:()=>{progress.archSeen=true;save();close();nextScene('carrier')}}])}
    if(id==='returnSeam')nextScene('seam');
