  function drawMysteryRings(){
    const depth=Math.max(0,Math.min(7,progress.mysteryDepth||0));
    if(depth<2)return;
    const anchor=sceneMagic[scene]?.[0];if(!anchor)return;
    const t=settings.reduced?0:renderTime;
    ctx.save();ctx.globalCompositeOperation='screen';ctx.lineWidth=1;
    for(let i=0;i<depth-1;i++){
      const drift=settings.reduced?0:Math.sin(t*.17+i*1.7)*depth*1.2;
      const cx=anchor[0]+Math.sin(i*2.4+depth)*depth*2+drift;
      const cy=anchor[1]+Math.cos(i*1.9+depth)*depth*1.3-drift*.35;
      ctx.strokeStyle=i%3===0?'#d9b77b':i%3===1?'#8fc9cb':'#cf8e8c';
      ctx.globalAlpha=.028+depth*.0035;
      ctx.setLineDash([46+i*11,27+i*7]);
      ctx.beginPath();ctx.ellipse(cx,cy,28+i*31+depth*5,12+i*18+depth*2,Math.sin(t*.05+i)*.08,0.22+i*.21,Math.PI*1.75+i*.13);ctx.stroke();
    }
    ctx.setLineDash([]);ctx.restore();
  }
