  function update(t){let dt=Math.min(.04,(t-last)/1000||0);last=t;renderTime+=dt;const speed=({slow:180,normal:285,fast:440})[settings.speed]||285;if(!menu.classList.contains('show')&&!modal.classList.contains('show')&&!worldMap.classList.contains('show')&&!pulse.classList.contains('show')&&!atlas.classList.contains('show')&&!heroPanel.classList.contains('show')){elapsed+=dt;let mx=Number(keys.has('right'))-Number(keys.has('left')),my=Number(keys.has('down'))-Number(keys.has('up'));if(mx||my){hero.to=null;pending=null;let length=Math.hypot(mx,my);hero.x=Math.max(90,Math.min(1510,hero.x+mx/length*speed*dt));hero.y=Math.max(625,Math.min(825,hero.y+my/length*speed*dt));if(mx)hero.facing=mx>0?1:-1;hero.walking=true}else if(hero.to){let dx=hero.to.x-hero.x,dy=hero.to.y-hero.y,d=Math.hypot(dx,dy),step=speed*dt;if(d<=step+3){hero.x=hero.to.x;hero.y=hero.to.y;hero.to=null;hero.walking=false;if(pending){let h=pending;pending=null;interact(h.id)}}else{hero.x+=dx/d*step;hero.y+=dy/d*step;hero.facing=dx>=0?1:-1;hero.walking=true}}else hero.walking=false;if(noticeUntil&&elapsed>noticeUntil){noticeUntil=0;prompt.textContent=vision?'Связи проявились. Выберите отмеченный объект.':'Нажмите на пол, чтобы идти. Осмотрите предметы.'}}render();requestAnimationFrame(update)}
